

-- =====================================================
-- PROJECT 5: STORE & REGIONAL ANALYSIS
-- TASK 1: REVENUE BY STORE
-- Business Question:
-- How much revenue does each store generate?
-- =====================================================

SELECT
    s.store_id,
    s.store_code,
    s.city,
    s.state,
    s.region,

    -- Calculate total revenue generated by the store
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue

FROM stores AS s

JOIN orders AS o
    ON s.store_id = o.store_id

JOIN order_items AS oi
    ON o.order_id = oi.order_id

GROUP BY
    s.store_id,
    s.store_code,
    s.city,
    s.state,
    s.region

ORDER BY
    total_revenue DESC;
    
    
    -- =====================================================
-- PROJECT 5: STORE & REGIONAL ANALYSIS
-- TASK 2: ORDERS BY STORE
-- Business Question:
-- How many orders does each store handle?
-- =====================================================

SELECT
    s.store_id,
    s.store_code,
    s.city,
    s.state,
    s.region,

    -- Count unique orders handled by each store
    COUNT(DISTINCT o.order_id) AS order_count

FROM stores AS s

JOIN orders AS o
    ON s.store_id = o.store_id

GROUP BY
    s.store_id,
    s.store_code,
    s.city,
    s.state,
    s.region

ORDER BY
    order_count DESC;
    
    
    -- =====================================================
-- PROJECT 5: STORE & REGIONAL ANALYSIS
-- TASK 3: AVERAGE ORDER VALUE BY STORE
-- Business Question:
-- Which stores generate the highest value per order?
-- =====================================================

SELECT
    s.store_id,
    s.store_code,
    s.city,
    s.state,
    s.region,

    -- Calculate average revenue generated per order
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    )
    /
    COUNT(DISTINCT o.order_id) AS average_order_value

FROM stores AS s

JOIN orders AS o
    ON s.store_id = o.store_id

JOIN order_items AS oi
    ON o.order_id = oi.order_id

GROUP BY
    s.store_id,
    s.store_code,
    s.city,
    s.state,
    s.region

ORDER BY
    average_order_value DESC;
    
    
    -- =====================================================
-- PROJECT 5: STORE & REGIONAL ANALYSIS
-- TASK 4: GROSS PROFIT BY STORE
-- Business Question:
-- Which stores generate the highest gross profit?
-- =====================================================

SELECT
    s.store_id,
    s.store_code,
    s.city,
    s.state,
    s.region,

    -- Calculate total gross profit generated by the store
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    ) AS total_profit

FROM stores AS s

JOIN orders AS o
    ON s.store_id = o.store_id

JOIN order_items AS oi
    ON o.order_id = oi.order_id

JOIN products AS p
    ON oi.product_id = p.product_id

GROUP BY
    s.store_id,
    s.store_code,
    s.city,
    s.state,
    s.region

ORDER BY
    total_profit DESC;
    
    
    -- =====================================================
-- PROJECT 5: STORE & REGIONAL ANALYSIS
-- TASK 5: PROFIT MARGIN BY STORE
-- Business Question:
-- Which stores have the highest gross profit margin?
-- =====================================================

SELECT
    s.store_id,
    s.store_code,
    s.city,
    s.state,
    s.region,

    -- Total revenue after discounts
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,

    -- Total gross profit
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    ) AS total_profit,

    -- Gross profit margin percentage
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    )
    /
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    )
    * 100 AS profit_margin_percent

FROM stores AS s

JOIN orders AS o
    ON s.store_id = o.store_id

JOIN order_items AS oi
    ON o.order_id = oi.order_id

JOIN products AS p
    ON oi.product_id = p.product_id

GROUP BY
    s.store_id,
    s.store_code,
    s.city,
    s.state,
    s.region

ORDER BY
    profit_margin_percent DESC;
    
    
    
