    -- =====================================================
-- PROJECT 5: STORE & REGIONAL ANALYSIS
-- TASK 11: STORE TYPE PERFORMANCE
-- Business Question:
-- How do different store types perform financially?
-- =====================================================

SELECT
    s.store_type,

    -- Total revenue generated by the store type
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    ) AS total_revenue,

    -- Number of unique orders
    COUNT(DISTINCT o.order_id) AS order_count,

    -- Average revenue generated per order
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    )
    /
    COUNT(DISTINCT o.order_id) AS average_order_value,

    -- Total gross profit
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    ) AS total_profit,

    -- Gross profit margin
    SUM(
        (
            oi.unit_price
            * (1 - oi.discount_percent / 100)
            - p.cost_price
        )
        * oi.quantity
    )
    /
    SUM(
        oi.quantity
        * oi.unit_price
        * (1 - oi.discount_percent / 100)
    )
    * 100 AS profit_margin_percent

FROM stores AS s

JOIN orders AS o
    ON s.store_id = o.store_id

JOIN order_items AS oi
    ON o.order_id = oi.order_id

JOIN products AS p
    ON oi.product_id = p.product_id

GROUP BY
    s.store_type

ORDER BY
    total_revenue DESC;
    
    
    -- =====================================================
-- PROJECT 5: STORE & REGIONAL ANALYSIS
-- TASK 12: STORE PERFORMANCE RANKING
-- Business Question:
-- Which stores are the strongest based on revenue,
-- while also showing their profit margin?
-- =====================================================

SELECT
    store_id,
    store_code,
    city,
    region,
    total_revenue,
    total_profit,
    profit_margin_percent,

    -- Rank stores from highest to lowest revenue
    RANK() OVER (
        ORDER BY total_revenue DESC
    ) AS revenue_rank

FROM (
    -- Calculate store-level financial metrics
    SELECT
        s.store_id,
        s.store_code,
        s.city,
        s.region,

        -- Total revenue
        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        ) AS total_revenue,

        -- Total gross profit
        SUM(
            (
                oi.unit_price
                * (1 - oi.discount_percent / 100)
                - p.cost_price
            )
            * oi.quantity
        ) AS total_profit,

        -- Gross profit margin
        SUM(
            (
                oi.unit_price
                * (1 - oi.discount_percent / 100)
                - p.cost_price
            )
            * oi.quantity
        )
        /
        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        )
        * 100 AS profit_margin_percent

    FROM stores AS s

    JOIN orders AS o
        ON s.store_id = o.store_id

    JOIN order_items AS oi
        ON o.order_id = oi.order_id

    JOIN products AS p
        ON oi.product_id = p.product_id

    GROUP BY
        s.store_id,
        s.store_code,
        s.city,
        s.region
) AS store_metrics

ORDER BY
    revenue_rank;
    
    
    
    -- =====================================================
-- PROJECT 5: STORE & REGIONAL ANALYSIS
-- TASK 13: TOP & BOTTOM STORES
-- Business Question:
-- Which stores belong to the top 10% and bottom 10%
-- based on revenue?
-- =====================================================

SELECT
    store_id,
    store_code,
    city,
    region,
    total_revenue,
    total_profit,
    profit_margin_percent,

    -- Divide stores into 10 revenue-based groups
    NTILE(10) OVER (
        ORDER BY total_revenue DESC
    ) AS revenue_decile,

    -- Label the top and bottom 10% of stores
    CASE
        WHEN NTILE(10) OVER (
            ORDER BY total_revenue DESC
        ) = 1
            THEN 'Top 10%'

        WHEN NTILE(10) OVER (
            ORDER BY total_revenue DESC
        ) = 10
            THEN 'Bottom 10%'

        ELSE 'Middle 80%'
    END AS performance_group

FROM (
    -- Calculate store-level performance
    SELECT
        s.store_id,
        s.store_code,
        s.city,
        s.region,

        -- Total revenue
        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        ) AS total_revenue,

        -- Total gross profit
        SUM(
            (
                oi.unit_price
                * (1 - oi.discount_percent / 100)
                - p.cost_price
            )
            * oi.quantity
        ) AS total_profit,

        -- Gross profit margin
        SUM(
            (
                oi.unit_price
                * (1 - oi.discount_percent / 100)
                - p.cost_price
            )
            * oi.quantity
        )
        /
        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        )
        * 100 AS profit_margin_percent

    FROM stores AS s

    JOIN orders AS o
        ON s.store_id = o.store_id

    JOIN order_items AS oi
        ON o.order_id = oi.order_id

    JOIN products AS p
        ON oi.product_id = p.product_id

    GROUP BY
        s.store_id,
        s.store_code,
        s.city,
        s.region
) AS store_metrics

ORDER BY
    revenue_decile,
    total_revenue DESC;
    
    
    
-- =====================================================
-- PROJECT 5: STORE & REGIONAL ANALYSIS
-- TASK 14: STORE EFFICIENCY ANALYSIS
-- =====================================================

SELECT
    store_id,
    store_code,
    city,
    region,
    total_revenue,
    order_count,
    average_order_value,

    -- Rank stores by revenue
    RANK() OVER (
        ORDER BY total_revenue DESC
    ) AS revenue_rank,

    -- Rank stores by order volume
    RANK() OVER (
        ORDER BY order_count DESC
    ) AS order_rank

FROM (
    -- Calculate store-level metrics
    SELECT
        s.store_id,
        s.store_code,
        s.city,
        s.region,

        -- Revenue after discounts
        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        ) AS total_revenue,

        -- Number of unique orders
        COUNT(DISTINCT o.order_id) AS order_count,

        -- Revenue per order
        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        )
        / COUNT(DISTINCT o.order_id) AS average_order_value

    FROM stores AS s

    JOIN orders AS o
        ON s.store_id = o.store_id

    JOIN order_items AS oi
        ON o.order_id = oi.order_id

    GROUP BY
        s.store_id,
        s.store_code,
        s.city,
        s.region
) AS store_metrics

ORDER BY
    revenue_rank;
    
    
    
   -- =====================================================
-- PROJECT 5: STORE & REGIONAL ANALYSIS
-- TASK 15: REGIONAL & STORE PORTFOLIO ANALYSIS
-- Business Question:
-- Which stores combine strong revenue with strong
-- profit margins?
-- =====================================================

SELECT
    store_id,
    store_code,
    city,
    region,
    total_revenue,
    total_profit,
    profit_margin_percent,

    -- Classify stores using revenue and profit margin
    CASE
        WHEN total_revenue >= 285000000
             AND profit_margin_percent >= 35.5
            THEN 'High Revenue / High Margin'

        WHEN total_revenue >= 285000000
             AND profit_margin_percent < 35.5
            THEN 'High Revenue / Low Margin'

        WHEN total_revenue < 285000000
             AND profit_margin_percent >= 35.5
            THEN 'Low Revenue / High Margin'

        ELSE 'Low Revenue / Low Margin'
    END AS portfolio_segment

FROM (
    -- Calculate store-level financial performance
    SELECT
        s.store_id,
        s.store_code,
        s.city,
        s.region,

        -- Total revenue after discounts
        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        ) AS total_revenue,

        -- Total gross profit
        SUM(
            (
                oi.unit_price
                * (1 - oi.discount_percent / 100)
                - p.cost_price
            )
            * oi.quantity
        ) AS total_profit,

        -- Gross profit margin
        SUM(
            (
                oi.unit_price
                * (1 - oi.discount_percent / 100)
                - p.cost_price
            )
            * oi.quantity
        )
        /
        SUM(
            oi.quantity
            * oi.unit_price
            * (1 - oi.discount_percent / 100)
        )
        * 100 AS profit_margin_percent

    FROM stores AS s

    JOIN orders AS o
        ON s.store_id = o.store_id

    JOIN order_items AS oi
        ON o.order_id = oi.order_id

    JOIN products AS p
        ON oi.product_id = p.product_id

    GROUP BY
        s.store_id,
        s.store_code,
        s.city,
        s.region
) AS store_metrics

ORDER BY
    CASE portfolio_segment
        WHEN 'High Revenue / High Margin' THEN 1
        WHEN 'High Revenue / Low Margin' THEN 2
        WHEN 'Low Revenue / High Margin' THEN 3
        ELSE 4
    END,
    total_revenue DESC; 
    
    
    
    